    faq_a4:                 "बिल्कुल। जनरेशन के बाद आपका कोर्स संग्रहीत नहीं किया जाता। आपका इतिहास सर्वर-साइड एन्क्रिप्टेड है और कभी साझा नहीं किया जाता। आप किसी भी समय अपना खाता हटा सकते हैं।",
    faq_a5:                 "हाँ। मासिक प्लान में कोई प्रतिबद्धता नहीं — सेटिंग्स से जब चाहें रद्द करें। वार्षिक प्लान मासिक मूल्य की तुलना में 42% की बचत करता है।",
    faq_a6:                 "StudyAI डेस्कटॉप, टैबलेट और मोबाइल पर काम करता है। कोई ऐप इंस्टॉल करने की जरूरत नहीं — सब कुछ तुम्हारे ब्राउज़र में होता है।",
    faq_a7:                 "हाँ, AI कभी-कभी गलतियाँ कर सकता है। StudyAI को अध्ययन सहायक के रूप में इस्तेमाल करें, लेकिन महत्वपूर्ण जानकारी के लिए हमेशा अपने आधिकारिक स्रोतों से जाँच करें।",
    faq_a8:                 "Studio, हमारे असिस्टेंट से बात करने के लिए नीचे दाईं ओर के चैट बटन पर क्लिक करें। जटिल प्रश्नों के लिए studyai.teame@gmail.com पर संपर्क करें।",
